// ──────────────────────────── tests ──────────────────────────────────────

test('lastChar returns the final character', () => {
  eq(lastChar('node'), 'e');
});

test('lastChar returns undefined for an empty string', () => {
  eq(lastChar(''), undefined);
});

test('dropLast removes n characters from the end', () => {
  eq(dropLast('report.txt', 4), 'report');
});

test('dropLast returns empty when n is bigger than the string', () => {
  eq(dropLast('abc', 10), '');
});

test('fileExtension reads the part after the LAST dot', () => {
  eq(fileExtension('archive.tar.gz'), 'gz');
});

test('fileExtension returns empty when there is no dot', () => {
  eq(fileExtension('README'), '');
});

test('isImage accepts known extensions in any case', () => {
  eq(isImage('Photo.PNG'), true);
  eq(isImage('cat.jpg'), true);
});

test('isImage rejects other files', () => {
  eq(isImage('notes.txt'), false);
  eq(isImage('pngfile'), false);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('splitFields splits on commas', () => {
  eq(splitFields('a,b,c'), ['a', 'b', 'c']);
});

test('splitFields trims the spaces around each field', () => {
  eq(splitFields(' name , email ,age'), ['name', 'email', 'age']);
});

test('splitFields on a single field gives a one-item array', () => {
  eq(splitFields('solo'), ['solo']);
});

test('joinPath glues the parts with slashes', () => {
  eq(joinPath(['usr', 'local', 'bin']), 'usr/local/bin');
});

test('joinPath of one part adds no slash', () => {
  eq(joinPath(['tmp']), 'tmp');
});

test('swapSeparator replaces EVERY occurrence, not just the first', () => {
  eq(swapSeparator('a-b-c', '-', '_'), 'a_b_c');
});

test('squish collapses runs of whitespace and trims the ends', () => {
  eq(squish('  the   quick \t brown '), 'the quick brown');
});

test('squish leaves an already clean string alone', () => {
  eq(squish('one two'), 'one two');
});

// ──────────────────────────── tests ──────────────────────────────────────

test('money turns cents into dollars with two decimals', () => {
  eq(money(350), '$3.50');
  eq(money(575), '$5.75');
});

test('money keeps the trailing zeros on small amounts', () => {
  eq(money(5), '$0.05');
  eq(money(0), '$0.00');
});

test('divider repeats a dash', () => {
  eq(divider(5), '-----');
});

test('formatLine right-aligns the price', () => {
  eq(formatLine('Coffee', 350, 20), 'Coffee         $3.50');
});

test('formatLine makes every line exactly `width` wide', () => {
  eq(formatLine('Tea', 75, 20).length, 20);
  eq(formatLine('Cinnamon roll', 1250, 20).length, 20);
});

test('receipt stacks the items, a divider, and the total', () => {
  eq(
    receipt(
      [
        ['Coffee', 350],
        ['Bagel', 225],
      ],
      20
    ),
    'Coffee         $3.50\n' +
      'Bagel          $2.25\n' +
      '--------------------\n' +
      'TOTAL          $5.75'
  );
});

test('receipt totals in cents, so no float dust appears', () => {
  const lines = receipt(
    [
      ['A', 10],
      ['B', 20],
      ['C', 3],
    ],
    12
  ).split('\n');
  eq(lines.at(-1), 'TOTAL  $0.33');
});

test('receipt works with a single item', () => {
  const lines = receipt([['Water', 199]], 16).split('\n');
  eq(lines.length, 3);
  eq(lines[0], 'Water      $1.99');
});

// ──────────────────────────── tests ──────────────────────────────────────

test('capitalize upper-cases the first letter', () => {
  eq(capitalize('ada'), 'Ada');
});

test('capitalize lower-cases the rest', () => {
  eq(capitalize('mARY'), 'Mary');
});

test('capitalize survives the empty string', () => {
  eq(capitalize(''), '');
});

test('titleCase capitalizes every word', () => {
  eq(titleCase('the great escape'), 'The Great Escape');
});

test('titleCase calms shouty input down', () => {
  eq(titleCase('THE GREAT ESCAPE'), 'The Great Escape');
});

test('initials take the first letter of each word', () => {
  eq(initials('ada lovelace'), 'AL');
  eq(initials('Grace Brewster Murray Hopper'), 'GBMH');
});

test('initials ignore extra whitespace', () => {
  eq(initials('  grace   hopper '), 'GH');
});

test('initials of a single name is a single letter', () => {
  eq(initials('cher'), 'C');
});

// ──────────────────────────── tests ──────────────────────────────────────

test('toCamelCase converts snake_case', () => {
  eq(toCamelCase('user_first_name'), 'userFirstName');
});

test('toCamelCase converts kebab-case', () => {
  eq(toCamelCase('user-first-name'), 'userFirstName');
});

test('toCamelCase converts spaced words and lowers the first one', () => {
  eq(toCamelCase('User first name'), 'userFirstName');
});

test('toSnakeCase splits camelCase at the capitals', () => {
  eq(toSnakeCase('userFirstName'), 'user_first_name');
  eq(toSnakeCase('apiKey'), 'api_key');
});

test('toSnakeCase splits after a digit too', () => {
  eq(toSnakeCase('address2Line'), 'address2_line');
});

test('toSnakeCase accepts kebab-case input', () => {
  eq(toSnakeCase('user-first-name'), 'user_first_name');
});

test('toKebabCase converts camelCase', () => {
  eq(toKebabCase('userFirstName'), 'user-first-name');
});

test('the converters round-trip', () => {
  eq(toCamelCase(toSnakeCase('userFirstName')), 'userFirstName');
  eq(toKebabCase(toCamelCase('user_first_name')), 'user-first-name');
});

// ──────────────────────────── tests ──────────────────────────────────────

test('truncate leaves short text alone', () => {
  eq(truncate('short', 10), 'short');
});

test('truncate leaves text of exactly max alone', () => {
  eq(truncate('exactlyten', 10), 'exactlyten');
});

test('truncate clips and appends an ellipsis', () => {
  eq(truncate('The quick brown fox', 10), 'The qui...');
});

test('the truncated result is never longer than max', () => {
  eq(truncate('The quick brown fox', 10).length, 10);
  eq(truncate('abcdefghijklmnop', 5).length, 5);
});

test('maskCard keeps the last four digits', () => {
  eq(maskCard('4111111111111111').slice(-4), '1111');
});

test('maskCard stars out everything else and keeps the length', () => {
  eq(maskCard('4111111111111111'), '************1111');
  eq(maskCard('378282246310005'), '***********0005');
});

test('maskCard leaves short values alone', () => {
  eq(maskCard('1234'), '1234');
  eq(maskCard('12'), '12');
});

// ──────────────────────────── tests ──────────────────────────────────────

test('lowercases and hyphenates words', () => {
  eq(slugify('Hello World'), 'hello-world');
});

test('drops punctuation', () => {
  eq(slugify('Hello, World!'), 'hello-world');
});

test('collapses a run of separators into one hyphen', () => {
  eq(slugify('a   b'), 'a-b');
  eq(slugify('why?! really'), 'why-really');
});

test('strips hyphens from both ends', () => {
  eq(slugify('  --Hi--  '), 'hi');
});

test('keeps digits', () => {
  eq(slugify('Top 10 JS Tips'), 'top-10-js-tips');
});

test('returns an empty string when nothing survives', () => {
  eq(slugify('!!!'), '');
  eq(slugify(''), '');
});

// ──────────────────────────── tests ──────────────────────────────────────

test('text that fits stays on one line', () => {
  eq(wordWrap('hello world', 20), ['hello world']);
});

test('fills each line greedily', () => {
  eq(wordWrap('the quick brown fox jumps', 10), [
    'the quick',
    'brown fox',
    'jumps',
  ]);
});

test('no line is wider than the width', () => {
  const lines = wordWrap('one two three four five six seven', 12);
  eq(
    lines.every((l) => l.length <= 12),
    true
  );
});

test('a word longer than the width gets a line of its own', () => {
  eq(wordWrap('hi extraordinarily ok', 5), ['hi', 'extraordinarily', 'ok']);
});

test('collapses newlines and double spaces', () => {
  eq(wordWrap('a  b\nc', 3), ['a b', 'c']);
});

test('empty or blank text wraps to no lines', () => {
  eq(wordWrap('', 10), []);
  eq(wordWrap('   ', 10), []);
});

test('joining the lines gives back every word in order', () => {
  const text = 'wrap this sentence at a narrow width please';
  eq(wordWrap(text, 9).join(' '), text);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('hasDigit finds a digit anywhere in the string', () => {
  eq(hasDigit('abc1'), true);
  eq(hasDigit('1abc'), true);
});

test('hasDigit is false when there are no digits', () => {
  eq(hasDigit('abc'), false);
  eq(hasDigit(''), false);
});

test('firstNumber returns the first run of digits as a string', () => {
  eq(firstNumber('order 66 ships 7 crates'), '66');
});

test('firstNumber returns null when there is no number', () => {
  eq(firstNumber('no digits here'), null);
});

test('allNumbers returns every run of digits', () => {
  eq(allNumbers('a1b22c333'), ['1', '22', '333']);
});

test('allNumbers keeps multi-digit runs together', () => {
  eq(allNumbers('room 101, floor 12'), ['101', '12']);
});

test('allNumbers returns an empty array, not null', () => {
  eq(allNumbers('nothing to see'), []);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('isHexColor accepts a 6-digit colour', () => {
  eq(isHexColor('#a3f2b1'), true);
  eq(isHexColor('#000000'), true);
});

test('isHexColor accepts the 3-digit shorthand in any case', () => {
  eq(isHexColor('#FFF'), true);
  eq(isHexColor('#0aF'), true);
});

test('isHexColor rejects a colour buried in a sentence', () => {
  eq(isHexColor('say #fff please'), false);
  eq(isHexColor('#fff!'), false);
});

test('isHexColor rejects the wrong number of digits', () => {
  eq(isHexColor('#ff'), false);
  eq(isHexColor('#12345'), false);
  eq(isHexColor('abc123'), false);
});

test('isHexColor rejects non-hex letters', () => {
  eq(isHexColor('#xyzxyz'), false);
});

test('isIdentifier accepts letters, digits and underscores', () => {
  eq(isIdentifier('user_name2'), true);
  eq(isIdentifier('_private'), true);
  eq(isIdentifier('x'), true);
});

test('isIdentifier rejects a leading digit', () => {
  eq(isIdentifier('2fast'), false);
});

test('isIdentifier rejects hyphens, spaces and emptiness', () => {
  eq(isIdentifier('user-name'), false);
  eq(isIdentifier('user name'), false);
  eq(isIdentifier(''), false);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('splitVersion returns the three parts', () => {
  eq(splitVersion('2.14.3'), [2, 14, 3]);
});

test('splitVersion returns numbers, not strings', () => {
  ok(typeof splitVersion('1.0.0')[0] === 'number');
});

test('splitVersion returns null for anything else', () => {
  eq(splitVersion('v2.14'), null);
  eq(splitVersion('1.2.3.4'), null);
});

test('parseLogLine names its parts', () => {
  eq(parseLogLine('2026-08-20 ERROR disk full'), {
    date: '2026-08-20',
    level: 'ERROR',
    message: 'disk full',
  });
});

test('parseLogLine keeps the whole message, spaces and all', () => {
  eq(parseLogLine('2026-01-02 WARN a b c').message, 'a b c');
});

test('parseLogLine returns null when the line does not fit', () => {
  eq(parseLogLine('junk'), null);
});

test('allTags collects every opening tag name in order', () => {
  eq(allTags('<b>hi</b> and <i>there</i>'), ['b', 'i']);
});

test('allTags keeps duplicates and returns [] when there are none', () => {
  eq(allTags('<b>a</b><b>c</b>'), ['b', 'b']);
  eq(allTags('plain text'), []);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('looksLikeId accepts a valid id', () => {
  eq(looksLikeId('a123'), true);
});

test('looksLikeId gives the same answer three calls in a row', () => {
  eq(looksLikeId('a123'), true);
  eq(looksLikeId('a123'), true);
  eq(looksLikeId('a123'), true);
});

test('looksLikeId rejects a non-id', () => {
  eq(looksLikeId('abc'), false);
  eq(looksLikeId('12'), false);
});

test('looksLikeId still works right after a rejection', () => {
  eq(looksLikeId('nope'), false);
  eq(looksLikeId('z999'), true);
});

test('countAll counts every id in the text', () => {
  eq(countAll('a123 b456 c789'), 3);
});

test('countAll is repeatable', () => {
  eq(countAll('a123 b456'), 2);
  eq(countAll('a123 b456'), 2);
});

test('countAll returns 0 when nothing matches', () => {
  eq(countAll('no ids here'), 0);
});

test('the two functions do not poison each other', () => {
  eq(countAll('a123 b456'), 2);
  eq(looksLikeId('a123'), true);
  eq(countAll('a123 b456'), 2);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('parsePairs builds an object of strings', () => {
  eq(parsePairs('a=1;b=2'), { a: '1', b: '2' });
  eq(parsePairs('n=42').n, '42');
});

test('parsePairs skips empty segments', () => {
  eq(parsePairs('a=1;;b=2;'), { a: '1', b: '2' });
});

test('parsePairs keeps an = that appears inside the value', () => {
  eq(parsePairs('q=a=b'), { q: 'a=b' });
});

test('parsePairs of an empty string is an empty object', () => {
  eq(parsePairs(''), {});
});

test('parseQueryString drops a leading question mark', () => {
  eq(parseQueryString('?a=1'), { a: '1' });
  eq(parseQueryString('a=1'), { a: '1' });
});

test('parseQueryString decodes + and percent escapes', () => {
  eq(parseQueryString('q=hello+world%21'), { q: 'hello world!' });
  eq(parseQueryString('name=Ada%20L'), { name: 'Ada L' });
});

test('parseQueryString collects a repeated key into an array', () => {
  eq(parseQueryString('a=1&b=two&a=3'), { a: ['1', '3'], b: 'two' });
  eq(parseQueryString('t=1&t=2&t=3'), { t: ['1', '2', '3'] });
});

test('parseQueryString gives a bare key an empty value', () => {
  eq(parseQueryString('flag&a=1'), { flag: '', a: '1' });
});

// ──────────────────────────── tests ──────────────────────────────────────

test('censor masks each banned word with stars of the same length', () => {
  eq(censor('I hate this bad code', ['hate', 'bad']), 'I **** this *** code');
});

test('censor is case-insensitive', () => {
  eq(censor('BAD stuff', ['bad']), '*** stuff');
});

test('censor only matches whole words', () => {
  eq(censor('badger stew', ['bad']), 'badger stew');
});

test('censor with an empty word list changes nothing', () => {
  eq(censor('anything goes', []), 'anything goes');
});

test('highlight brackets every occurrence, keeping its casing', () => {
  eq(highlight('Cat cat CAT', 'cat'), '[Cat] [cat] [CAT]');
});

test('highlight leaves text without a match alone', () => {
  eq(highlight('dogs only', 'cat'), 'dogs only');
});

test('expandTemplate fills placeholders from the object', () => {
  eq(expandTemplate('Hi {name}, {n} new', { name: 'Ada', n: 3 }), 'Hi Ada, 3 new');
});

test('expandTemplate leaves unknown placeholders untouched', () => {
  eq(expandTemplate('Hi {nope}', {}), 'Hi {nope}');
  eq(expandTemplate('{a} and {b}', { a: 'x' }), 'x and {b}');
});

// ──────────────────────────── tests ──────────────────────────────────────

test('buildMap looks values up by object identity', () => {
  const ada = { name: 'Ada' };
  const bob = { name: 'Bob' };
  const roles = buildMap([
    [ada, 'admin'],
    [bob, 'guest'],
  ]);
  eq(roles.get(ada), 'admin');
  eq(roles.get(bob), 'guest');
});

test('a look-alike object is a different key', () => {
  const ada = { name: 'Ada' };
  const roles = buildMap([[ada, 'admin']]);
  eq(roles.get({ name: 'Ada' }), undefined);
});

test('the number 1 and the string "1" are different keys', () => {
  const m = buildMap([
    [1, 'num'],
    ['1', 'str'],
  ]);
  eq(m.get(1), 'num');
  eq(m.get('1'), 'str');
  eq(m.size, 2);
});

test('a Map remembers insertion order, even for numeric keys', () => {
  eq(
    [...buildMap([
      [2, 'two'],
      [1, 'one'],
    ]).keys()],
    [2, 1]
  );
});

test('mapToObject converts string-keyed entries', () => {
  eq(mapToObject(new Map([['a', 1], ['b', 2]])), { a: 1, b: 2 });
});

test('mapToObject of an empty Map is an empty object', () => {
  eq(mapToObject(new Map()), {});
});

test('objectToMap gives a real Map with a size', () => {
  const m = objectToMap({ a: 1, b: 2 });
  eq(m.size, 2);
  eq(m.get('b'), 2);
});

test('the two conversions round-trip', () => {
  eq(mapToObject(objectToMap({ x: 1, y: 2 })), { x: 1, y: 2 });
});

// ──────────────────────────── tests ──────────────────────────────────────

test('frequency counts repeats', () => {
  eq(frequency(['a', 'b', 'a']), new Map([['a', 2], ['b', 1]]));
});

test('frequency returns a Map you can query', () => {
  eq(frequency(['x', 'x', 'x']).get('x'), 3);
});

test('frequency of an empty list is an empty Map', () => {
  eq(frequency([]).size, 0);
});

test('frequency keeps first-seen order', () => {
  eq([...frequency(['b', 'a', 'b']).keys()], ['b', 'a']);
});

test('frequency counts numbers and strings separately', () => {
  const f = frequency([1, '1', 1]);
  eq(f.get(1), 2);
  eq(f.get('1'), 1);
});

test('mostCommon returns the item with the highest count', () => {
  eq(mostCommon(['b', 'a', 'a']), 'a');
});

test('mostCommon breaks a tie in favour of the first seen', () => {
  eq(mostCommon(['b', 'a', 'a', 'b']), 'b');
  eq(mostCommon([]), undefined);
});

test('invert swaps keys and values', () => {
  eq(invert(new Map([['ada', 1], ['bob', 2]])), new Map([[1, 'ada'], [2, 'bob']]));
});

// ──────────────────────────── tests ──────────────────────────────────────

test('unique removes repeats and keeps first-seen order', () => {
  eq(unique([3, 1, 3, 2, 1]), [3, 1, 2]);
});

test('unique returns an array, not a Set', () => {
  eq(Array.isArray(unique(['a'])), true);
});

test('unique does not coerce types', () => {
  eq(unique([1, '1']), [1, '1']);
});

test('unique leaves a clean array alone', () => {
  eq(unique(['x', 'y']), ['x', 'y']);
  eq(unique([]), []);
});

test('hasDuplicates spots a repeat', () => {
  eq(hasDuplicates([1, 2, 2]), true);
  eq(hasDuplicates(['a', 'b', 'a']), true);
});

test('hasDuplicates is false for a clean list', () => {
  eq(hasDuplicates([1, 2, 3]), false);
  eq(hasDuplicates([]), false);
});

test('firstDuplicate returns the value that repeats first', () => {
  eq(firstDuplicate(['a', 'b', 'c', 'b', 'a']), 'b');
});

test('firstDuplicate returns null when everything is unique', () => {
  eq(firstDuplicate(['a', 'b']), null);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('union holds every member of both, without duplicates', () => {
  eq(union(new Set([1, 2]), new Set([2, 3])), new Set([1, 2, 3]));
  eq(union(new Set(['a']), new Set(['a'])).size, 1);
});

test('union does not modify its arguments', () => {
  const a = new Set([1]);
  union(a, new Set([2]));
  eq(a, new Set([1]));
});

test('intersection keeps only shared members', () => {
  eq(intersection(new Set([1, 2, 3]), new Set([2, 3, 4])), new Set([2, 3]));
});

test('intersection of disjoint sets is empty', () => {
  eq(intersection(new Set([1]), new Set([2])).size, 0);
});

test('difference keeps members of a that are missing from b', () => {
  eq(difference(new Set([1, 2]), new Set([2, 3])), new Set([1]));
});

test('difference is not symmetric', () => {
  const a = new Set([1, 2]);
  const b = new Set([2, 3]);
  eq(difference(b, a), new Set([3]));
});

test('isSubset is true when every member of a is in b', () => {
  eq(isSubset(new Set([1]), new Set([1, 2])), true);
  eq(isSubset(new Set([1, 2]), new Set([1, 2])), true);
});

test('isSubset is false when one member is missing, true when empty', () => {
  eq(isSubset(new Set([1, 9]), new Set([1, 2])), false);
  eq(isSubset(new Set(), new Set([1])), true);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('the store remembers metadata per object', () => {
  const store = createMetaStore();
  const req = { url: '/a' };
  store.set(req, { startedAt: 5 });
  eq(store.get(req), { startedAt: 5 });
});

test('the object itself stays clean', () => {
  const store = createMetaStore();
  const req = { url: '/a' };
  store.set(req, { startedAt: 5 });
  eq(Object.keys(req), ['url']);
  eq(JSON.stringify(req), '{"url":"/a"}');
});

test('look-alike objects get separate metadata', () => {
  const store = createMetaStore();
  const a = { id: 1 };
  const b = { id: 1 };
  store.set(a, 'first');
  store.set(b, 'second');
  eq(store.get(a), 'first');
  eq(store.get(b), 'second');
});

test('get returns undefined for an unknown object', () => {
  const store = createMetaStore();
  eq(store.get({}), undefined);
});

test('memoize computes once per object', () => {
  const calc = spy((o) => o.n * 2);
  const memo = memoizeByObject(calc);
  const user = { n: 21 };
  eq(memo(user), 42);
  eq(memo(user), 42);
  eq(calc.callCount, 1);
});

test('memoize recomputes for a different object', () => {
  const calc = spy((o) => o.n * 2);
  const memo = memoizeByObject(calc);
  memo({ n: 1 });
  memo({ n: 1 });
  eq(calc.callCount, 2);
});

test('the cached value is the very same reference', () => {
  const memo = memoizeByObject((o) => ({ doubled: o.n * 2 }));
  const user = { n: 2 };
  ok(memo(user) === memo(user));
});

test('a cached undefined does not trigger a recompute', () => {
  const calc = spy(() => undefined);
  const memo = memoizeByObject(calc);
  const key = {};
  memo(key);
  memo(key);
  eq(calc.callCount, 1);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('formatDate pads the month and day, counting months from 1', () => {
  eq(formatDate(new Date(Date.UTC(2026, 0, 5))), '2026-01-05');
});

test('formatDate handles two-digit months and days', () => {
  eq(formatDate(new Date(Date.UTC(2026, 11, 25))), '2026-12-25');
});

test('formatDate ignores the machine timezone', () => {
  eq(formatDate(new Date('2026-03-01T23:30:00Z')), '2026-03-01');
  eq(formatDate(new Date('2026-03-01T00:30:00Z')), '2026-03-01');
});

test('parseDate returns midnight UTC on that day', () => {
  eq(parseDate('2026-08-20').toISOString(), '2026-08-20T00:00:00.000Z');
});

test('parseDate handles single-digit months', () => {
  eq(parseDate('2026-01-02').toISOString(), '2026-01-02T00:00:00.000Z');
});

test('parseDate and formatDate round-trip', () => {
  eq(formatDate(parseDate('1999-12-31')), '1999-12-31');
  eq(formatDate(parseDate('2000-02-29')), '2000-02-29');
});

test('isWeekend is true on Saturday and Sunday', () => {
  eq(isWeekend(parseDate('2026-08-22')), true);
  eq(isWeekend(parseDate('2026-08-23')), true);
});

