    '| ada   | js    |',
    '| grace | cobol |',
  ]);
});

test('markdownTable stringifies values that are not strings', () => {
  eq(markdownTable([{ n: 1 }, { n: 22 }]), [
    '| n  |',
    '| -- |',
    '| 1  |',
    '| 22 |',
  ]);
});

test('markdownTable leaves a missing key blank', () => {
  eq(markdownTable([{ a: 'x', b: 'y' }, { a: 'zz' }]), [
    '| a  | b |',
    '| -- | - |',
    '| x  | y |',
    '| zz |   |',
